class ExpiredCoupon extends StatelessWidget {
  const ExpiredCoupon({super.key, required this.coupon});
  final Coupon coupon;

  @override
  Widget build(BuildContext context) => Opacity(
        opacity: 0.5, // the whole group goes through an intermediate buffer
        child: Row(children: [
          Image.asset(coupon.imagePath, width: 48),
          Text(coupon.title),
        ]),
      );
}

class ExpiredCoupon extends StatelessWidget {
  const ExpiredCoupon({super.key, required this.coupon});
  final Coupon coupon;

  @override
  Widget build(BuildContext context) => Row(children: [
        // Each piece draws itself semi-transparent: no group to buffer
        Image.asset(
          coupon.imagePath,
          width: 48,
          color: const Color.fromRGBO(255, 255, 255, 0.5),
          colorBlendMode: BlendMode.modulate,
        ),
        Text(
          coupon.title,
          style: const TextStyle(color: Color.fromRGBO(0, 0, 0, 0.5)),
        ),
      ]);
}
